import type { components } from "@octokit/openapi-types";
import { RequestError } from "@octokit/request-error";
import _ from "lodash";
import type { Client } from "../client.ts";

const keywords = [
  "close",
  "closes",
  "closed",
  "fix",
  "fixes",
  "fixed",
  "resolve",
  "resolves",
  "resolved",
];

class ReferenceSearch {
  /**
   * The client that instantiated this template
   */
  client: Client;
  /**
   * The number of the pull request this search applies to
   */
  number: number;
  /**
   * The description of the pull request this search applies to
   */
  body: string;
  /**
   * The name of the repository of the pull request this search applies to
   */
  repoName: string;
  /**
   * The owner of the repository of the pull request this search applies to
   */
  repoOwner: string;

  constructor(
    client: Client,
    pull:
      | components["schemas"]["pull-request-simple"]
      | components["schemas"]["webhook-pull-request-synchronize"]["pull_request"]
      | components["schemas"]["pull-request-webhook"],
    repo: components["schemas"]["repository"],
  ) {
    this.client = client;
    this.number = pull.number;
    this.body = pull.body ?? "";
    this.repoName = repo.name;
    this.repoOwner = repo.owner.login;
  }

  /**
   * Finds all open referenced issues from a given string
   * by identifying keywords specified above.
   *
   * Keywords are sourced from
   * https://help.github.com/articles/closing-issues-using-keywords/
   *
   * Referenced issues are only closed when pull requests are merged,
   * not necessarily when commits are merged.
   *
   * @param strings Strings to find references in.
   * @returns Sorted array of all referenced issue numbers.
   */

  async find(strings: string[]) {
    const regex = new RegExp(
      `(?:${keywords.map((keyword) => _.escapeRegExp(keyword)).join("|")}):? #([0-9]+)`,
      "giv",
    );
    const issues = strings.flatMap((string) =>
      Array.from(string.matchAll(regex), (match) => Number(match[1])),
    );
    const uniqueIssues = [...new Set(issues)];

    // check matches for valid issue references
    const statusCheck = uniqueIssues.map(async (number) => {
      let issue;
      try {
        issue = await this.client.issues.get({
          owner: this.repoOwner,
          repo: this.repoName,
          issue_number: number,
        });
      } catch (error) {
        if (error instanceof RequestError && error.status === 404) return false;
        throw error;
      }

      // valid references are open issues
      const isValid = !issue.data.pull_request && issue.data.state === "open";
      return isValid ? number : false;
    });
    // statusCheck is an array of promises, so use Promise.all
    const matchStatuses = await Promise.all(statusCheck);
    // remove strings that didn't contain any references
    const filteredMatches = matchStatuses.filter((number) => number !== false);
    return filteredMatches.toSorted((a, b) => a - b);
  }

  async getBody() {
    const bodyReferences = await this.find([this.body]);
    return bodyReferences;
  }

  async getCommits() {
    const commits = await this.client.pulls.listCommits({
      owner: this.repoOwner,
      repo: this.repoName,
      pull_number: this.number,
    });

    const msgs = commits.data.map((c) => c.commit.message);
    const commitReferences = await this.find(msgs);

    return commitReferences;
  }
}

export default ReferenceSearch;

import { test, type TestContext } from "node:test";
import type { EmitterWebhookEvent } from "@octokit/webhooks";
import nock from "nock";
import { partialMock } from "partial-mock";
import client from "../../../src/client.ts";
import * as member from "../../../src/events/member.ts";

const payload: EmitterWebhookEvent<"member">["payload"] = partialMock({
  action: "removed",
  repository: {
    name: "zulipbot",
    full_name: "zulip/zulipbot",
    owner: { login: "zulip" },
  },
  member: {
    login: "octokitten",
  },
});

void test("member: Ignore if payload action isn't added", async (t: TestContext) => {
  const response = await member.run.call(client, payload);

  t.assert.strictEqual(response, undefined);
});

const payload2: EmitterWebhookEvent<"member">["payload"] = partialMock({
  action: "added",
  repository: payload.repository,
  member: payload.member,
});

void test("member: Ignore if there aren't any claim command aliases", async (t: TestContext) => {
  client.cfg.issues.commands.assign.claim = [];
  const response = await member.run.call(client, payload2);

  t.assert.strictEqual(response, undefined);
});

void test("member: Ignore if there aren't any recorded invites", async (t: TestContext) => {
  client.cfg.issues.commands.assign.claim = ["claim"];
  const response = await member.run.call(client, payload2);

  t.assert.strictEqual(response, undefined);
});

void test("member: Assign successfully if invite was found", async (t: TestContext) => {
  client.invites.set("octokitten@zulip/zulipbot", 69);

  const scope = nock("https://api.github.com")
    .post("/repos/zulip/zulipbot/issues/69/assignees", {
      assignees: ["octokitten"],
    })
    .reply(200, { assignees: ["octokitten"] });

  const response = await member.run.call(client, payload2);

  t.assert.ok(!client.invites.has("octokitten@zulip/zulipbot"));
  t.assert.strictEqual(response, true);

  scope.done();
});

void test("member: Warn if issue assignment failed", async (t: TestContext) => {
  client.invites.set("octokitten@zulip/zulipbot", 69);

  const error = "**ERROR:** Issue claiming failed (no assignee was added).";

  const scope = nock("https://api.github.com")
    .post("/repos/zulip/zulipbot/issues/69/assignees", {
      assignees: ["octokitten"],
    })
    .reply(200, { assignees: [] })
    .post("/repos/zulip/zulipbot/issues/69/comments", { body: error })
    .reply(200);

  await member.run.call(client, payload2);

  t.assert.ok(!client.invites.has("octokitten@zulip/zulipbot"));

  scope.done();
});

